/**
 * Sub-entrypoint for voice-related imports — re-exports the LiveKit
 * plugin namespaces that LuaVoice's class-form `stt` / `tts` accept.
 *
 * Devs who write a code-defined LuaVoice with the plugin route can keep
 * `lua-cli` as the only dependency they import:
 *
 * ```typescript
 * import { LuaVoice } from 'lua-cli';
 * import { deepgram, elevenlabs, inference } from 'lua-cli/voice';
 *
 * export default new LuaVoice({
 *   llm: 'openai/gpt-5.2-chat-latest',                      // string descriptor → Inference
 *   stt: new deepgram.STT({ model: 'nova-3' }),             // class form → direct plugin
 *   tts: new elevenlabs.TTS({ voiceId: 'abc', model: 'eleven_v3' }),
 * });
 * ```
 *
 * Without this sub-entrypoint, devs would need to add
 * `@livekit/agents-plugin-deepgram` etc. as direct dependencies in
 * their own project. Routing through `lua-cli` keeps the dev-side
 * `package.json` clean.
 *
 * Note: these are *type-only relevant* at compile time — the lua-cli
 * compiler ASTs the dev's source and extracts `{ kind: 'plugin',
 * provider, class, options }` for the wire shape. The actual
 * `new deepgram.STT({...})` construction happens in the lua-livekit
 * worker's dispatch path, not the dev's process. The re-exports here
 * give devs full TypeScript autocomplete on plugin-specific options.
 *
 * `inference` is re-exported from `@livekit/agents` (the parent
 * package) so devs can use the typed `new inference.LLM/STT/TTS({...})`
 * form without adding `@livekit/agents` to their dev project.
 */
export * as deepgram from '@livekit/agents-plugin-deepgram';
export * as elevenlabs from '@livekit/agents-plugin-elevenlabs';
export * as openai from '@livekit/agents-plugin-openai';
export * as google from '@livekit/agents-plugin-google';
export * as xai from '@livekit/agents-plugin-xai';
export { inference } from '@livekit/agents';
